c = mix(c, vec3(1.0,0.5,0.18), smoothstep(0.6,0.8,n)*0.7);         // 橙色丝缕
c = mix(c, vec3(1.0,0.3,0.7), smoothstep(0.66,0.85,1.0-n)*0.35);   // 品红暗部
